curl -X POST https://apx.didit.me/auth/v2/programmatic/register/ \
  -H "Content-Type: application/json" \
  -d '{
    "email": "you@yourdomain.com",
    "password": "MyStr0ng!Pass"
  }'

import requests

resp = requests.post(
    "https://apx.didit.me/auth/v2/programmatic/register/",
    json={
        "email": "you@yourdomain.com",
        "password": "MyStr0ng!Pass",
    },
    timeout=10,
)
resp.raise_for_status()
print(resp.json())
# {'message': 'Registration successful...', 'email': 'you@yourdomain.com'}

const resp = await fetch(
  "https://apx.didit.me/auth/v2/programmatic/register/",
  {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      email: "you@yourdomain.com",
      password: "MyStr0ng!Pass",
    }),
  },
);
if (!resp.ok) throw new Error(`Register failed: ${resp.status}`);
const data = await resp.json();
console.log(data);

curl -X POST https://apx.didit.me/auth/v2/programmatic/verify-email/ \
  -H "Content-Type: application/json" \
  -d '{
    "email": "you@yourdomain.com",
    "code": "A3K9F2"
  }'

const resp = await fetch(
  "https://apx.didit.me/auth/v2/programmatic/verify-email/",
  {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      email: "you@yourdomain.com",
      code: "A3K9F2",
    }),
  },
);
if (!resp.ok) throw new Error(`Verify failed: ${resp.status}`);
const { application, access_token } = await resp.json();
// application.api_key -> x-api-key for verification.didit.me/v3
// access_token -> Authorization: Bearer ... for this auth API

